<?php declare(strict_types=1);header('Content-Type: application/json; charset=utf-8');require __DIR__.'/inc/db.php';require __DIR__.'/inc/order_service.php';try{require_customer();$token=(string)($_SERVER['HTTP_X_CSRF_TOKEN']??'');if($token===''||!hash_equals(csrf_token(),$token)){http_response_code(419);throw new RuntimeException('Your session expired. Refresh checkout and try again.');}$payload=json_decode((string)file_get_contents('php://input'),true,32,JSON_THROW_ON_ERROR);$payload['payment']='gcash';$o=create_normal_order($pdo,$payload,user_id());$q=$pdo->prepare('SELECT normal_order_id FROM order_headers WHERE id=?');$q->execute([$o['id']]);echo json_encode(['success'=>true,'redirect'=>'gcash_xendit.php?order_id='.(int)$q->fetchColumn()]);}catch(Throwable $e){if(http_response_code()<400)http_response_code(422);echo json_encode(['success'=>false,'message'=>$e->getMessage()]);}
